from frame import *

def bplan(n, p, bg, cur=False, hot=False):
    return card(f'<div style="height: 70px; border-radius: 18px; background: {bg}; border: 2px solid {OL}; display: flex; align-items: center; padding: 0 14px"><span style="padding: 3px 12px; border-radius: 999px; background: #FFFFFF; border: 2px solid {OL}; font-weight: 800; font-size: 13px; color: {OL}">{e(n)}</span></div>', f'<div style="font-family: {HF}; font-weight: 800; font-size: 36px">{p}<span style="font-size: 14px; color: {T["mu"]}; font-family: {BF}; font-weight: 500"> / mo</span></div>', btn('Current plan' if cur else 'Choose', 'secondary' if cur else ('primary' if hot else 'secondary'), None, None if cur else 'Plans-Checkout.dc.html', full=True), pad=14, style=f'border: {"3px solid "+T["acc"] if hot else "1px solid "+T["bd"]}')
PLANS = lambda: grid([bplan('Starter','$19','#59D8FF'), bplan('Creator Pro','$49','#2F5BFF',cur=True), bplan('Business','$99','#B6F24A',hot=True), bplan('Agency','$249','#FF4FB8')], cols=4, minw=220)

@screen('BI-01','Plan & usage','Billing','billing',('filled','loading',('free','Free plan')))
def _(st, f, t):
    if st == 'loading': app_page(f, t, 'billing', sk_head() + grid([sk_card(160,3), sk_card(160,4)], cols=2, gap=20) + sk_table(4, 3), h=1050); return
    if st == 'free':
        inner = page_head('Billing & usage', None, [btn('Upgrade','cta',None,'Plans.dc.html',arrow=True)], eb='Billing') + f'<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 24px; padding: 28px; border-radius: 32px; background: {T["s1"]}; border: 1px solid {T["bd"]}">{art("gift", 220)}<div style="flex: 1 1 360px; display: flex; flex-direction: column; gap: 10px">{H("You’re on Free", 30)}{P("1 manual agent, 1 account, very limited credits and no autonomous publishing. Try paid features for 3 days, no card needed.", size=15)}{row(btn("Start 3-day trial","cta",None,"Trial.dc.html",arrow=True), btn("Compare plans","secondary",None,"Plans.dc.html"), gap=10)}</div></div>' + card(card_head('This month'), meter('Credits used', 70, '70 of 100'), meter('Agents', 100, '1 of 1', 'ai'), meter('Accounts', 100, '1 of 1', 'lime'), pad=24)
        app_page(f, t, 'billing', inner, h=1050); return
    plan_card = card(row(col(small('Your plan'), H('Creator Pro',32), small('$49 / month · renews 1 Dec 2026'), gap=4), grow(), btn('Change plan','secondary',None,'Plans.dc.html'), gap=10), kv([('Payment', row(chip('Paystack','neutral'), 'Card ending 4417', gap=6)),('Billing currency','USD (paid in NGN at checkout)')]), pad=24)
    usage = card(card_head('This month', small('Limits are provisional')), meter('Credits used', 38, '760 of 2,000 · 1,240 left'), meter('Agents', 60, '3 of 5', 'ai'), meter('Social accounts', 33, '2 of 6', 'lime'), meter('Storage', 20, '20 of 100 GB', 'ok'), pad=24)
    est = table(['Workspace / agent','Estimated','Actual','Difference'], [('Budget Shorts','540','512', chip('−28 refunded','ok')),('Recipe Reels','300','300', chip('even','neutral')),('Podcast Clipper','0','0','—')])
    inner = page_head('Billing & usage', None, [btn('Top up','primary','plus','TopUp.dc.html')], eb='Billing') + grid([plan_card, usage], cols=2, gap=20) + section_title('Estimated vs actual this month', link('Full ledger →','Ledger.dc.html')) + est
    app_page(f, t, 'billing', inner, h=1150)

@screen('BI-02','Plans & checkout','Plans','billing',('filled',('checkout','Checkout'),('processing','Processing'),('success','Success'),('declined','Declined')))
def _(st, f, t):
    head = page_head('Choose a plan', 'Prices in USD. You pay in naira at Paystack.', [], crumbs='Billing')
    m = ''
    if st == 'checkout': m = overlay(row(bubble('card','blue',56), col(H('Upgrade to Business',26), small('Billed monthly · cancel any time'), gap=2), gap=12) + kv([('Price','$99.00 / month'),('Today, prorated','$50.00'),('You’ll pay in naira','≈ ₦[AMOUNT]: exact amount shown by Paystack before you confirm'),('Payment provider','Paystack')]) + check('I authorize Nelio to charge me $99 every month until I cancel.', True) + btn('Continue to Paystack','cta',None,'Plans-Processing.dc.html','lg',True,arrow=True) + small('No charge happens until you confirm on the next screen.'), maxw=580)
    elif st == 'processing': m = overlay(f'<div style="display: flex; justify-content: center"><span style="display: inline-flex; {A("spin")}">{icon("refresh",48,T["accTx"])}</span></div>' + H('Waiting for Paystack…',26) + P('Don’t close this tab. This usually takes a few seconds.'), maxw=460)
    elif st == 'success': m = overlay(f'<div style="display: flex; justify-content: center">{art("success",240)}</div>' + H('Welcome to Business!',28) + P('Receipt sent to ada@adastudio.ng. Your new limits are live.') + btn('Back to Command Center','cta',None,'CommandCenter.dc.html',full=True,arrow=True), maxw=480)
    elif st == 'declined': m = overlay(f'<div style="display: flex; justify-content: center">{art("payment",220)}</div>' + H('Paystack declined the card',26) + P('You weren’t charged. Try another card, or pay by bank transfer.') + row(btn('Cancel','ghost'), grow(), btn('Try again','cta',arrow=True), gap=10), maxw=480)
    app_page(f, t, 'billing', head + PLANS(), h=1000, modal=m)

