        card(toggle('Auto top-up', False, 'Off by default. If on, we add 1,500 credits when you drop below 100, at most once a week.'), pad=22) + row(btn('Buy 1,500 credits · $15','cta',None,'Plans-Processing.dc.html','lg',arrow=True), small('Paid via Paystack in NGN'), gap=14)
