setnav = lambda a: tabs(['Profile','Security','Appearance','Notifications','Privacy'], a)
def sload(f, t, active='settings'): app_page(f, t, active, sk_head() + sk('420px',40,999) + card(sk_lines(5), pad=24) + card(sk_lines(3), pad=24), h=900)
