def theme_card(name, ic, sel, bgc, fgc, acc):
    return f'<button type="button" aria-pressed="{"true" if sel else "false"}" style="padding: 14px; border-radius: 26px; border: 3px solid {T["acc"] if sel else T["bd"]}; background: {T["s1"]}; cursor: pointer; display: flex; flex-direction: column; gap: 12px; font-family: {BF}; color: {T["tx"]}; text-align: left"><span style="height: 130px; border-radius: 18px; background: {bgc}; display: flex; flex-direction: column; gap: 8px; padding: 14px; box-sizing: border-box; border: 1px solid {T["bd"]}"><span style="width: 60%; height: 12px; border-radius: 6px; background: {fgc}"></span><span style="width: 40%; height: 26px; border-radius: 999px; background: {acc}"></span><span style="width: 80%; height: 10px; border-radius: 5px; background: {fgc}; opacity: 0.35"></span></span><span style="display: flex; align-items: center; gap: 8px; font-weight: 800">{icon(ic,18)}{e(name)}</span></button>'
